            );
        }
        if let Some(ticket) = cache.buffers[1].take() {
            capture(
                &mut failure,
                control.drop_reserved_with_wasi(
                    take(&mut cache.pins),
                    ticket,
                    wasi.map(AccountedWasi::usage),
